mapper.insert:
/* DefaultSchGenMapper.insertDefaultSchDayIfAbsent */
INSERT INTO TB_USER_WORK_PLAN (
      CMPNY_CD
    , SITE_CD
    , USER_CD
    , WORK_YMD
    , WORK_PLAN_CD
    , GEN_SOURCE
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
SELECT
      #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{workYmd}
    , #{schCd}
    , 'DEFAULT_SCH'
    , #{operatorNo}
    , NOW()
    , #{operatorNo}
    , NOW()
  FROM DUAL
 WHERE NOT EXISTS (
        SELECT 1
          FROM TB_USER_WORK_PLAN WP
         WHERE WP.CMPNY_CD = #{cmpnyCd}
           AND WP.SITE_CD  = #{siteCd}
           AND WP.USER_CD  = #{userCd}
           AND WP.WORK_YMD = #{workYmd}
       )

mapper.update:
/* DefaultSchGenMapper.updateFutureDefaultSch */
UPDATE TB_USER_WORK_PLAN WP
   SET WP.WORK_PLAN_CD = #{newSchCd}
     , WP.UPDATE_NO    = #{operatorNo}
     , WP.UPDATE_DATE  = NOW()
 WHERE WP.CMPNY_CD   = #{cmpnyCd}
   AND WP.SITE_CD    = #{siteCd}
   AND WP.USER_CD    = #{userCd}
   AND WP.WORK_YMD   > #{fromYmd}
   AND WP.GEN_SOURCE = 'DEFAULT_SCH'
   AND NOT EXISTS (
        SELECT 1
          FROM TB_USER_LEAVE_USE U
         WHERE U.CMPNY_CD     = #{cmpnyCd}
           AND U.USER_CD      = #{userCd}
           AND U.LEAVE_STATUS = 'CONFIRMED'
           AND U.DEL_YN       = 'N'
           AND U.USE_UNIT_TYPE <> '00'
           AND U.START_DATE  <= WP.WORK_YMD
           AND U.END_DATE    >= WP.WORK_YMD
       )
   AND NOT EXISTS (
        SELECT 1
          FROM TB_USER_ATTD_REQ RQ
         WHERE RQ.CMPNY_CD   = #{cmpnyCd}
           AND RQ.USER_CD    = #{userCd}
           AND RQ.WORK_YMD   = WP.WORK_YMD
           AND RQ.REQ_TYPE   = '05'
           AND RQ.REQ_STATUS = '01'
           AND RQ.DEL_YN     = 'N'
           AND RQ.START_TIME IS NOT NULL
           AND RQ.END_TIME   IS NOT NULL
       )

mapper.select:
/* DefaultSchGenMapper.countFutureDefaultSchLockedDays */
SELECT COUNT(*)
  FROM TB_USER_WORK_PLAN WP
 WHERE WP.CMPNY_CD   = #{cmpnyCd}
   AND WP.SITE_CD    = #{siteCd}
   AND WP.USER_CD    = #{userCd}
   AND WP.WORK_YMD   > #{fromYmd}
   AND WP.GEN_SOURCE = 'DEFAULT_SCH'
   AND (
        EXISTS (
            SELECT 1
              FROM TB_USER_LEAVE_USE U
             WHERE U.CMPNY_CD     = #{cmpnyCd}
               AND U.USER_CD      = #{userCd}
               AND U.LEAVE_STATUS = 'CONFIRMED'
               AND U.DEL_YN       = 'N'
               AND U.USE_UNIT_TYPE <> '00'
               AND U.START_DATE  <= WP.WORK_YMD
               AND U.END_DATE    >= WP.WORK_YMD
           )
        OR EXISTS (
            SELECT 1
              FROM TB_USER_ATTD_REQ RQ
             WHERE RQ.CMPNY_CD   = #{cmpnyCd}
               AND RQ.USER_CD    = #{userCd}
               AND RQ.WORK_YMD   = WP.WORK_YMD
               AND RQ.REQ_TYPE   = '05'
               AND RQ.REQ_STATUS = '01'
               AND RQ.DEL_YN     = 'N'
               AND RQ.START_TIME IS NOT NULL
               AND RQ.END_TIME   IS NOT NULL
           )
       )

/* DefaultSchGenMapper.countActiveSchOnSite */
SELECT COUNT(*)
  FROM TB_SCH_MGMT M
 WHERE M.CMPNY_CD = #{cmpnyCd}
   AND M.SITE_CD  = #{siteCd}
   AND M.SCH_CD   = #{schCd}
   AND M.USE_YN   = 'Y'
   AND (
         M.APPLY_DATE  <=  #{asOfDate}
         OR EXISTS (
             SELECT 1
               FROM TB_SCH_MGMT_HIST H
              WHERE H.CMPNY_CD = M.CMPNY_CD
                AND H.SITE_CD  = M.SITE_CD
                AND H.SCH_CD   = M.SCH_CD
                AND H.APPLY_DATE  <=  #{asOfDate}
         )
       )

/* DefaultSchGenMapper.selectUserSiteCd */
SELECT U.SITE_CD
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.USER_CD  = #{userCd}
 LIMIT 1

mapper.update:
/* DefaultSchGenMapper.updateUserDefaultSch */
UPDATE TB_USER
   SET DEFAULT_SCH_CD       = #{defaultSchCd}
     , DEFAULT_SCH_SET_DATE = NOW()
     , UPDATE_NO            = #{operatorNo}
     , UPDATE_DATE          = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}

mapper.select:
/* DefaultSchGenMapper.selectHolidayRuleMmdds */
SELECT CONCAT(R.HOLIDAY_MM, R.HOLIDAY_DD)
  FROM TB_HOLIDAY_RULE R
 WHERE R.CMPNY_CD = #{cmpnyCd}
   AND R.USE_YN   = 'Y'
